package com.chatgptcourses.payments.refunds;

import static com.chatgptcourses.payments.refunds.RefundTypes.*;
import static com.chatgptcourses.payments.refunds.RefundStore.*;
import com.chatgptcourses.commerce.service.CommerceAuthorization;
import com.chatgptcourses.commerce.service.PaymentGateway;
import com.chatgptcourses.notifications.TransactionalNotifications;
import com.chatgptcourses.payments.config.StripeSettings;
import com.chatgptcourses.payments.service.PaymentGatewayException;
import com.chatgptcourses.shared.config.RuntimeProperties;
import com.chatgptcourses.shared.http.ApiError;
import com.chatgptcourses.shared.http.EntityTags;
import com.chatgptcourses.shared.http.RevisionPreconditions;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

/** Operator consent precedes the financial POST. Provider networking never holds a DB transaction. */
@Service
public class RefundService {
    private final RefundStore db;private final CommerceAuthorization auth;private final PaymentGateway gateway;private final StripeSettings stripe;
    private final RefundSettings settings;private final TransactionalNotifications notifications;private final RuntimeProperties runtime;private final TransactionTemplate tx;
    public RefundService(RefundStore db,CommerceAuthorization auth,PaymentGateway gateway,StripeSettings stripe,RefundSettings settings,TransactionalNotifications notifications,RuntimeProperties runtime,PlatformTransactionManager manager){this.db=db;this.auth=auth;this.gateway=gateway;this.stripe=stripe;this.settings=settings;this.notifications=notifications;this.runtime=runtime;this.tx=new TransactionTemplate(manager);}

    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public RefundContext context(UUID actor,UUID orderId,boolean admin){auth.require(actor,admin?"refunds.admin.read":"refunds.read");var order=ownedOrder(actor,orderId,admin);return context(order);}
    private RefundContext context(Order o){var t=db.totals(o);String reason=!"PAID".equals(o.payment())?"NOT_PAID":o.review()?"RECONCILIATION_REQUIRED":t.confirmed()>=o.amount()?"FULLY_REFUNDED":t.available()==0?"AMOUNT_RESERVED":null;
        if(reason==null&&Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM refund_requests WHERE order_id=? AND state='REQUESTED')",Boolean.class,o.id())))reason="REQUEST_ALREADY_EXISTS";
        return new RefundContext(o.id(),o.revision(),o.payment(),o.fulfillment(),o.currency(),"PAID".equals(o.payment())?o.amount():0,t.confirmed(),t.reserved(),t.available(),o.review()?"NEEDS_REVIEW":"CURRENT",reason==null,reason,db.lines(o));}
    @Transactional
    public RefundRequestCreation createRequest(UUID actor,UUID accountContext,UUID orderId,String idempotencyKey,CreateRefundRequest command){auth.mutation(actor,accountContext,"refunds.request");check(command!=null);reason(command.reason());UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(orderId,command));
        var o=ownedOrder(actor,orderId,false);db.lockOwner(o.owner());o=db.order(orderId,true);auth.mutation(actor,accountContext,"refunds.request");UUID old=db.replay(actor,"REQUEST",key,hash,false);if(old!=null)return new RefundRequestCreation(db.requestView(db.request(old,false)),false);
        var context=context(o);if(!context.canRequest())throw error("REQUEST_ALREADY_EXISTS".equals(context.requestUnavailableReason())?ApiError.REFUND_REQUEST_EXISTS:ApiError.REFUND_NOT_AVAILABLE);
        UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO refund_requests(id,owner_id,order_id,state,reason) VALUES(?,?,?,'REQUESTED',?)",id,actor,orderId,command.reason());db.remember(actor,"REQUEST",key,hash,id,null);db.audit(actor,orderId,id,null,"REQUEST","REQUESTED",command.reason());return new RefundRequestCreation(db.requestView(db.request(id,false)),true);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public RefundRequestView request(UUID actor,UUID id,boolean admin){auth.require(actor,admin?"refunds.admin.read":"refunds.read");var r=db.request(id,false);if(!admin&&!actor.equals(r.owner()))throw error(ApiError.RESOURCE_NOT_FOUND);return db.requestView(r);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public RefundRequestPage requests(UUID actor,boolean admin,String state,UUID orderId,int page,int pageSize){auth.require(actor,admin?"refunds.admin.read":"refunds.read");page(page,pageSize);check(state==null||Set.of("REQUESTED","APPROVED","REJECTED").contains(state));var args=new ArrayList<Object>();String where=" WHERE 1=1";if(!admin){where+=" AND owner_id=?";args.add(actor);}if(orderId!=null){where+=" AND order_id=?";args.add(orderId);}if(state!=null){where+=" AND state=?";args.add(state);}long total=Objects.requireNonNull(db.jdbc.queryForObject("SELECT count(*) FROM refund_requests"+where,Long.class,args.toArray()));args.add(pageSize);args.add((long)page*pageSize);var ids=db.jdbc.query("SELECT id FROM refund_requests"+where+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(rs,n)->rs.getObject(1,UUID.class),args.toArray());return new RefundRequestPage(ids.stream().map(id->db.requestView(db.request(id,false))).toList(),page,pageSize,total);}

    @Transactional(propagation=Propagation.NOT_SUPPORTED)
    public RefundPreview preview(UUID actor,UUID accountContext,UUID id,String ifMatch,PreviewRefund command){auth.mutation(actor,accountContext,"refunds.decide");var r=db.request(id,false);refreshOrder(r.order());return tx.execute(status->{var locked=lockRequest(actor,accountContext,id,"refunds.decide");RevisionPreconditions.requireMatch(ifMatch,requestTag(locked));return preview(locked,db.order(locked.order(),true),command);});}
    private RefundPreview preview(Request r,Order o,PreviewRefund command){if(!"REQUESTED".equals(r.state())||!"PAID".equals(o.payment())||o.review())throw error(ApiError.REFUND_NOT_AVAILABLE);check(command!=null);var totals=db.totals(o);if(command.amountMinor()<1||command.amountMinor()>99_999_999||command.amountMinor()>totals.available())throw error(ApiError.REFUND_AMOUNT_UNAVAILABLE);
        boolean full=totals.confirmed()+totals.reserved()+command.amountMinor()==o.amount();var lines=db.lines(o);var allocations=validateAllocations(command.allocations(),command.amountMinor(),lines,full);
        String fingerprint=db.fingerprint(Arrays.asList(r.id(),r.revision(),o.id(),o.revision(),totals.confirmed(),totals.reserved(),command.amountMinor(),allocations,full));return new RefundPreview(r.id(),r.revision(),o.id(),o.revision(),o.currency(),command.amountMinor(),totals.available(),full,allocations,lines,fingerprint);}
    @Transactional(propagation=Propagation.NOT_SUPPORTED)
    public RefundDecisionResult decide(UUID actor,UUID accountContext,UUID id,String ifMatch,String idempotencyKey,DecideRefund command){auth.mutation(actor,accountContext,"refunds.decide");check(command!=null&&command.outcome()!=null&&Set.of("APPROVE","REJECT").contains(command.outcome()));reason(command.reason());UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,command));var initial=db.request(id,false);
        // Only an approval needs current financial facts. A rejection is not a provider operation.
        if("APPROVE".equals(command.outcome())&&db.replay(actor,"DECISION",key,hash,false)==null)refreshOrder(initial.order());
        return tx.execute(status->{var r=lockRequest(actor,accountContext,id,"refunds.decide");UUID old=db.replay(actor,"DECISION",key,hash,false);if(old!=null){var view=db.requestView(db.request(old,false));return new RefundDecisionResult(view,view.decision().operationId()==null?null:db.operationView(actor,db.operation(view.decision().operationId(),false)));}
            RevisionPreconditions.requireMatch(ifMatch,requestTag(r));if(!"REQUESTED".equals(r.state()))throw error(ApiError.CONFLICT);var o=db.order(r.order(),true);RefundPreview p=null;
            if("APPROVE".equals(command.outcome())){check(command.amountMinor()!=null&&command.previewFingerprint()!=null);p=preview(r,o,new PreviewRefund(command.amountMinor(),command.allocations()));if(!MessageDigest.isEqual(p.fingerprint().getBytes(java.nio.charset.StandardCharsets.US_ASCII),command.previewFingerprint().getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw error(ApiError.REFUND_PREVIEW_CHANGED);}
            else check(command.amountMinor()==null&&command.previewFingerprint()==null&&command.allocations()!=null&&command.allocations().isEmpty());
            UUID decision=UUID.randomUUID(),operation=p==null?null:UUID.randomUUID();db.jdbc.update("INSERT INTO refund_decisions(id,request_id,actor_id,outcome,reason,amount_minor,currency,allocations_json,preview_fingerprint) VALUES(?,?,?,?,?,?,?,?::jsonb,?)",decision,id,actor,command.outcome(),command.reason(),p==null?null:p.amountMinor(),p==null?null:p.currency(),db.json(p==null?List.of():p.allocations()),p==null?null:p.fingerprint());
            if(p!=null){db.jdbc.update("INSERT INTO refund_operations(id,order_id,owner_id,request_id,decision_id,origin,account_id,state,amount_minor,currency,provider_idempotency_key,allocations_json) VALUES(?,?,?,?,?,'LOCAL_DECISION',?,'PREPARED',?,?,?,?::jsonb)",operation,o.id(),o.owner(),id,decision,stripe.accountId(),p.amountMinor(),o.currency(),"cc-refund-"+operation,db.json(p.allocations()));db.jdbc.update("INSERT INTO refund_reservations(operation_id,order_id,owner_id,amount_minor) VALUES(?,?,?,?)",operation,o.id(),o.owner(),p.amountMinor());}
            db.jdbc.update("UPDATE refund_requests SET state=?,decision_id=?,revision=revision+1,updated_at=greatest(updated_at,created_at,clock_timestamp()) WHERE id=?",p==null?"REJECTED":"APPROVED",decision,id);db.remember(actor,"DECISION",key,hash,id,null);db.audit(actor,o.id(),id,operation,"DECISION",p==null?"REJECTED":"APPROVED",command.reason());return new RefundDecisionResult(db.requestView(db.request(id,false)),operation==null?null:db.operationView(actor,db.operation(operation,false)));});}

    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public RefundOperationView operation(UUID actor,UUID id,boolean admin){auth.require(actor,admin?"refunds.admin.read":"refunds.read");var p=db.operation(id,false);if(!admin&&!actor.equals(p.owner()))throw error(ApiError.RESOURCE_NOT_FOUND);return db.operationView(actor,p);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public RefundOperationPage operations(UUID actor,boolean admin,String state,UUID orderId,int page,int pageSize){auth.require(actor,admin?"refunds.admin.read":"refunds.read");page(page,pageSize);check(state==null||STATES.contains(state));var args=new ArrayList<Object>();String where=" WHERE 1=1";if(!admin){where+=" AND owner_id=?";args.add(actor);}if(orderId!=null){where+=" AND order_id=?";args.add(orderId);}if(state!=null){where+=" AND state=?";args.add(state);}long total=Objects.requireNonNull(db.jdbc.queryForObject("SELECT count(*) FROM refund_operations"+where,Long.class,args.toArray()));args.add(pageSize);args.add((long)page*pageSize);return new RefundOperationPage(db.jdbc.query("SELECT * FROM refund_operations"+where+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(rs,n)->db.operationView(actor,db.operation(rs,n)),args.toArray()),page,pageSize,total);}
    @Transactional(propagation=Propagation.NOT_SUPPORTED)
    public RefundOperationView execute(UUID actor,UUID accountContext,UUID id,String ifMatch,String idempotencyKey,RefundAction command){auth.mutation(actor,accountContext,"refunds.execute");check(command!=null);reason(command.reason());UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,command));var initial=db.operation(id,false);
        if(db.replay(actor,"EXECUTE",key,hash,true)!=null)return operation(actor,id,true);if(!gateway.configured())throw error(ApiError.PAYMENT_NOT_CONFIGURED);
        refreshOrder(initial.order());var claim=tx.execute(status->{var p=lockOperation(actor,accountContext,id,"refunds.execute");if(db.replay(actor,"EXECUTE",key,hash,true)!=null)return (Execution)null;RevisionPreconditions.requireMatch(ifMatch,operationTag(db.operationView(actor,p)));if(!"PREPARED".equals(p.state()))throw error(ApiError.REFUND_OPERATION_NOT_EXECUTABLE);var o=db.order(p.order(),true);var totals=db.totals(o);if(o.review()||!"PAID".equals(o.payment())||o.intent()==null||totals.confirmed()+totals.reserved()>o.amount())throw error(ApiError.REFUND_AMOUNT_UNAVAILABLE);
            var parameters=new RefundParameters(id,o.id(),o.intent(),p.amount(),o.currency());String json=db.json(parameters);UUID lease=UUID.randomUUID();db.jdbc.update("UPDATE refund_operations SET state='CALLING',payment_intent_id=?,request_json=?::jsonb,request_hash=?,lease_id=?,lease_until=clock_timestamp()+(?*interval '1 millisecond'),updated_at=greatest(updated_at,created_at,clock_timestamp()),revision=revision+1 WHERE id=?",o.intent(),json,db.hash(parameters),lease,settings.leaseDuration().toMillis(),id);db.remember(actor,"EXECUTE",key,hash,null,id);db.audit(actor,o.id(),p.request(),id,"EXECUTE","CALLING",command.reason());return new Execution(parameters,p.providerKey(),lease);});
        if(claim==null)return operation(actor,id,true);
        try{var facts=gateway.createRefund(claim.parameters(),claim.providerKey());tx.executeWithoutResult(status->{var p=lockOperation(actor,accountContext,id,"refunds.execute");applyOne(db.order(p.order(),true),facts);summarize(p.order());db.enqueue(p.order());});}
        catch(PaymentGatewayException failure){tx.executeWithoutResult(status->{var p=db.operation(id,false);db.lockOwner(p.owner());db.order(p.order(),true);p=db.operation(id,true);if(!"CALLING".equals(p.state())||!Objects.equals(p.lease(),claim.lease()))return;db.state(id,failure.ambiguous()?"UNKNOWN":"FAILED",safeCode(failure.reason()));if(!failure.ambiguous())db.release(id,"FAILED");db.audit(actor,p.order(),p.request(),id,"PROVIDER_RESULT",failure.ambiguous()?"UNKNOWN":"FAILED",null);db.enqueue(p.order());});}
        catch(RuntimeException unknown){tx.executeWithoutResult(status->{var p=db.operation(id,false);db.lockOwner(p.owner());db.order(p.order(),true);p=db.operation(id,true);if("CALLING".equals(p.state())&&Objects.equals(p.lease(),claim.lease())){db.state(id,"UNKNOWN","REFUND_RESULT_UNKNOWN");db.enqueue(p.order());}});}
        return operation(actor,id,true);}
    @Transactional
    public RefundOperationView cancel(UUID actor,UUID accountContext,UUID id,String ifMatch,String idempotencyKey,RefundAction command){check(command!=null);reason(command.reason());UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,command));var p=lockOperation(actor,accountContext,id,"refunds.execute");if(db.replay(actor,"CANCEL",key,hash,true)!=null)return db.operationView(actor,p);RevisionPreconditions.requireMatch(ifMatch,operationTag(db.operationView(actor,p)));if(!"PREPARED".equals(p.state())||p.requestJson()!=null)throw error(ApiError.REFUND_OPERATION_NOT_EXECUTABLE);db.state(id,"CANCELED",null);db.release(id,"CANCELED");db.remember(actor,"CANCEL",key,hash,null,id);db.audit(actor,p.order(),p.request(),id,"CANCEL","CANCELED",command.reason());return db.operationView(actor,db.operation(id,false));}
    @Transactional
    public RefundOperationView reconcile(UUID actor,UUID accountContext,UUID id,String ifMatch,String idempotencyKey,RefundAction command){check(command!=null);reason(command.reason());UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,command));var p=lockOperation(actor,accountContext,id,"refunds.reconcile");if(db.replay(actor,"RECONCILE",key,hash,true)!=null)return db.operationView(actor,p);RevisionPreconditions.requireMatch(ifMatch,operationTag(db.operationView(actor,p)));if(Set.of("PREPARED","CANCELED").contains(p.state()))throw error(ApiError.REFUND_OPERATION_NOT_EXECUTABLE);db.enqueue(p.order());db.remember(actor,"RECONCILE",key,hash,null,id);db.audit(actor,p.order(),p.request(),id,"RECONCILE","REQUESTED",command.reason());return db.operationView(actor,p);}
    @Transactional
    public RefundOperationView decideExternalAccess(UUID actor,UUID accountContext,UUID id,String ifMatch,String idempotencyKey,ResolveExternalRefund command){check(command!=null);reason(command.reason());UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,command));var p=lockOperation(actor,accountContext,id,"refunds.decide");if(db.replay(actor,"ACCESS",key,hash,true)!=null)return db.operationView(actor,p);RevisionPreconditions.requireMatch(ifMatch,operationTag(db.operationView(actor,p)));if(!"STRIPE_DASHBOARD".equals(p.origin())||!"SUCCEEDED".equals(p.state())||!"NEEDS_REVIEW".equals(p.access()))throw error(ApiError.REFUND_OPERATION_NOT_EXECUTABLE);var o=db.order(p.order(),true);var allocations=validateAllocations(command.allocations(),p.amount(),db.lines(o),db.totals(o).confirmed()>=o.amount());db.jdbc.update("INSERT INTO refund_access_decisions(operation_id,actor_id,reason,allocations_json) VALUES(?,?,?,?::jsonb)",id,actor,command.reason(),db.json(allocations));applyAccess(o,p,allocations);db.remember(actor,"ACCESS",key,hash,null,id);db.audit(actor,o.id(),p.request(),id,"ACCESS_DECISION","APPLIED",command.reason());summarize(o.id());return db.operationView(actor,db.operation(id,false));}

    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public EntitlementPage entitlements(UUID actor,String locale,int page,int pageSize){auth.require(actor,"entitlements.read");check(Set.of("fr","en").contains(locale));page(page,pageSize);boolean test=Set.of("local","test").contains(runtime.environment());String where=" WHERE g.owner_id=?"+(test?"":" AND g.origin_type='ORDER_LINE'");long total=Objects.requireNonNull(db.jdbc.queryForObject("SELECT count(*) FROM access_grants g"+where,Long.class,actor));var rows=db.jdbc.query("""
        SELECT g.*,r.order_id,v.version_number,e.title,EXISTS(SELECT 1 FROM refund_origin_revocations x WHERE x.grant_id=g.id) AS refund_reason,
          CASE WHEN g.revoked_at IS NOT NULL THEN 'REVOKED' WHEN g.starts_at>clock_timestamp() THEN 'NOT_STARTED' WHEN g.expires_at<=clock_timestamp() THEN 'EXPIRED' ELSE 'ACTIVE' END AS effective_state
        FROM access_grants g JOIN pedagogical_versions v ON v.id=g.version_id LEFT JOIN order_resources r ON r.id=g.order_resource_id
        LEFT JOIN content_translations t ON t.pedagogical_version_id=g.version_id AND t.locale=? LEFT JOIN editorial_revisions e ON e.id=t.published_revision_id
        """+where+" ORDER BY g.created_at DESC,g.id LIMIT ? OFFSET ?",(rs,n)->{UUID order=uuid(rs,"order_id");String title=rs.getString("title");if(order!=null){var snapshot=db.order(order,false).snapshot();title=snapshot.resources().stream().filter(r->r.id().equals(uuidUnchecked(rs,"order_resource_id"))).map(r->r.title()).findFirst().orElse(title);}return new EntitlementSummary(uuid(rs,"id"),rs.getString("origin_type"),order,uuid(rs,"order_resource_id"),uuid(rs,"resource_id"),uuid(rs,"version_id"),rs.getInt("version_number"),title==null?"Resource / Ressource":title,List.copyOf(Arrays.asList(db.mapper.readValue(rs.getString("locales"),String[].class))),rs.getString("version_policy"),rs.getString("effective_state"),instant(rs,"revoked_at")==null?null:rs.getBoolean("refund_reason")?"REFUND":"ACCESS_REVOKED",instant(rs,"starts_at"),instant(rs,"expires_at"),instant(rs,"revoked_at"));},locale,actor,pageSize,(long)page*pageSize);return new EntitlementPage(rows,page,pageSize,total);}

    /** Called inside verified Checkout reconciliation; a counter alone does not authorize revocation. */
    @Transactional(propagation=Propagation.MANDATORY)
    public void observeCheckoutRefund(UUID orderId,long amount){if(amount<=0)return;var o=db.order(orderId,true);boolean unmatched=amount>db.totals(o).confirmed();db.jdbc.update("UPDATE orders SET payment_refunded=true,refund_review_required=refund_review_required OR ?,revision=revision+1 WHERE id=? AND(NOT payment_refunded OR(? AND NOT refund_review_required))",unmatched,orderId,unmatched);db.enqueue(orderId);}
    public boolean activationBlocked(UUID orderId){return Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT refund_full OR refund_review_required FROM orders WHERE id=?",Boolean.class,orderId));}
    @Transactional
    public UUID requestOrderReconciliation(UUID actor,UUID context,UUID orderId){auth.mutation(actor,context,"refunds.reconcile");var o=db.order(orderId,false);db.lockOwner(o.owner());o=db.order(orderId,true);auth.mutation(actor,context,"refunds.reconcile");if(!"PAID".equals(o.payment())||o.session()==null)throw error(ApiError.RECONCILIATION_UNAVAILABLE);db.enqueue(orderId);return db.jdbc.queryForObject("SELECT id FROM refund_reconciliation_jobs WHERE order_id=?",UUID.class,orderId);}
    public void refreshOrder(UUID orderId){var o=db.order(orderId,false);if(!"PAID".equals(o.payment())||o.session()==null)throw error(ApiError.REFUND_NOT_AVAILABLE);String intent=o.intent();if(intent==null){var f=gateway.retrieveCheckoutFacts(o.session());if(f.livemode()||!stripe.accountId().equals(f.accountId())||!o.id().equals(f.orderId())||!o.checkout().equals(f.operationId())||!"succeeded".equals(f.paymentIntentStatus())||f.amountReceived()==null||f.amountReceived()!=o.amount()||!o.currency().equals(f.currency()))throw new PaymentGatewayException("REFUND_PAYMENT_INVALID",false);intent=f.paymentIntentId();}applyFacts(orderId,gateway.retrieveRefunds(intent));}
    public void applyFacts(UUID orderId,RefundPaymentFacts facts){tx.executeWithoutResult(status->{var o=db.order(orderId,false);db.lockOwner(o.owner());o=db.order(orderId,true);if(facts==null||!facts.complete()||facts.livemode()||!stripe.accountId().equals(facts.accountId())||facts.amountReceived()!=o.amount()||!o.currency().equals(facts.currency())||o.intent()!=null&&!o.intent().equals(facts.paymentIntentId()))throw new PaymentGatewayException("REFUND_PAYMENT_INVALID",false);
        if(o.intent()==null)db.jdbc.update("UPDATE checkout_operations SET payment_intent_id=?,updated_at=greatest(updated_at,created_at,clock_timestamp()),revision=revision+1 WHERE id=?",facts.paymentIntentId(),o.checkout());
        Set<String> unique=new HashSet<>();for(var f:facts.refunds()){if(!unique.add(f.refundId())||!Objects.equals(f.paymentIntentId(),facts.paymentIntentId())||!Objects.equals(f.chargeId(),facts.chargeId()))throw new PaymentGatewayException("REFUND_RESPONSE_INVALID",false);applyOne(o,f);}
        for(var p:db.jdbc.query("SELECT * FROM refund_operations WHERE order_id=? AND state='CALLING' AND lease_until<=clock_timestamp()",db::operation,o.id()))db.state(p.id(),"UNKNOWN","REFUND_SUBMISSION_LEASE_EXPIRED");
        for(var p:db.jdbc.query("SELECT * FROM refund_operations WHERE order_id=? AND state='UNKNOWN' AND provider_refund_id IS NULL AND updated_at<clock_timestamp()-interval '1 hour'",db::operation,o.id()))db.state(p.id(),"NEEDS_REVIEW","REFUND_NOT_FOUND_AFTER_WINDOW");
        summarize(o.id());});}
    private void applyOne(Order o,RefundFacts f){if(f==null||f.livemode()||!stripe.accountId().equals(f.accountId())||!o.currency().equals(f.currency())||f.amountMinor()<1||f.amountMinor()>o.amount()||f.refundId()==null||!f.refundId().matches("re_[A-Za-z0-9_]{1,250}")||!PROVIDER_STATES.contains(f.status()))throw new PaymentGatewayException("REFUND_RESPONSE_INVALID",false);
        // A bound provider id is authoritative. Dashboard metadata is merely an optional correlation hint.
        Operation p=null;var bound=db.jdbc.query("SELECT * FROM refund_operations WHERE account_id=? AND provider_refund_id=?",db::operation,stripe.accountId(),f.refundId());
        if(!bound.isEmpty()){p=bound.getFirst();if(!p.order().equals(o.id())||p.amount()!=f.amountMinor()||p.intent()!=null&&!p.intent().equals(f.paymentIntentId()))throw new PaymentGatewayException("REFUND_REFERENCE_INVALID",false);}
        if(p==null&&f.operationId()!=null&&o.id().equals(f.orderId())){
            var candidates=db.jdbc.query("SELECT * FROM refund_operations WHERE id=? AND order_id=? AND origin='LOCAL_DECISION'",db::operation,f.operationId(),o.id());
            if(!candidates.isEmpty()){var candidate=candidates.getFirst();if(candidate.amount()==f.amountMinor()&&candidate.currency().equals(f.currency())&&candidate.intent()!=null&&candidate.intent().equals(f.paymentIntentId())&&candidate.requestJson()!=null&&(candidate.providerRefund()==null||candidate.providerRefund().equals(f.refundId())))p=candidate;}
        }
        String target=switch(f.status()){case "succeeded"->"SUCCEEDED";case "failed"->"FAILED";case "canceled"->"CANCELED";case "requires_action"->"REQUIRES_ACTION";default->"PENDING";};
        if(p==null){UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO refund_operations(id,order_id,owner_id,origin,account_id,state,amount_minor,currency,provider_refund_id,payment_intent_id,provider_idempotency_key,allocations_json,access_state,confirmed_at) VALUES(?,?,?,'STRIPE_DASHBOARD',?,?,?,?,?,?,?,'[]'::jsonb,'NEEDS_REVIEW',CASE WHEN ? THEN clock_timestamp() ELSE NULL END)",id,o.id(),o.owner(),stripe.accountId(),target,f.amountMinor(),o.currency(),f.refundId(),f.paymentIntentId(),"external-"+f.refundId(),"SUCCEEDED".equals(target));p=db.operation(id,true);db.audit(null,o.id(),null,id,"PROVIDER_DISCOVERED",target,null);if(!Set.of("SUCCEEDED","FAILED","CANCELED").contains(target))db.jdbc.update("INSERT INTO refund_reservations(operation_id,order_id,owner_id,amount_minor) VALUES(?,?,?,?)",id,o.id(),o.owner(),p.amount());}
        else{
            if(p.confirmed()!=null&&Set.of("FAILED","CANCELED").contains(target)){if(!"NEEDS_REVIEW".equals(p.state()))db.state(p.id(),"NEEDS_REVIEW","REFUND_CHANGED_AFTER_SUCCESS");return;}
            if("SUCCEEDED".equals(p.state())&&!"SUCCEEDED".equals(target))return;
            if(Set.of("FAILED","CANCELED").contains(p.state())&&!target.equals(p.state())){db.state(p.id(),"NEEDS_REVIEW","REFUND_CHANGED_AFTER_TERMINAL");return;}
            if(!target.equals(p.state())||p.providerRefund()==null){db.jdbc.update("UPDATE refund_operations SET state=?,provider_refund_id=?,payment_intent_id=coalesce(payment_intent_id,?),last_error_code=?,lease_id=NULL,lease_until=NULL,confirmed_at=CASE WHEN ? THEN coalesce(confirmed_at,clock_timestamp()) ELSE confirmed_at END,updated_at=greatest(updated_at,created_at,clock_timestamp()),revision=revision+1 WHERE id=?",target,f.refundId(),f.paymentIntentId(),f.failureCode()==null?null:safeCode("REFUND_"+f.failureCode().toUpperCase(Locale.ROOT)),"SUCCEEDED".equals(target),p.id());db.audit(null,o.id(),p.request(),p.id(),"PROVIDER_STATUS",target,null);p=db.operation(p.id(),true);}
        }
        if(Set.of("SUCCEEDED","FAILED","CANCELED").contains(p.state()))db.release(p.id(),p.state());
        if("SUCCEEDED".equals(p.state())&&"LOCAL_DECISION".equals(p.origin())&&Set.of("NOT_APPLIED","NEEDS_REVIEW").contains(p.access()))applyAccess(o,p,p.allocations());
        if("SUCCEEDED".equals(p.state())){String email=db.jdbc.queryForObject("SELECT normalized_email FROM user_accounts WHERE id=?",String.class,o.owner());notifications.refundUpdated(p.id(),o.owner(),email,o.snapshot().locale());}
    }
    private void applyAccess(Order o,Operation p,List<RefundAllocation> allocations){boolean revoke=false;for(var a:allocations)if("REVOKE".equals(a.accessAction())){revoke=true;block(o,p,a.orderResourceId());}String state=revoke?"APPLIED":"KEPT";if(!state.equals(p.access()))db.jdbc.update("UPDATE refund_operations SET access_state=?,updated_at=greatest(updated_at,created_at,clock_timestamp()),revision=revision+1 WHERE id=?",state,p.id());}
    private void block(Order o,Operation p,UUID line){if(o.snapshot().resources().stream().noneMatch(r->r.id().equals(line)))throw error(ApiError.INVALID_REFUND_ALLOCATION);db.jdbc.update("INSERT INTO refund_access_blocks(order_resource_id,operation_id) VALUES(?,?) ON CONFLICT DO NOTHING",line,p.id());var grants=db.jdbc.query("UPDATE access_grants SET revoked_at=greatest(created_at,clock_timestamp()) WHERE order_resource_id=? AND revoked_at IS NULL RETURNING id",(rs,n)->rs.getObject(1,UUID.class),line);for(var id:grants)db.jdbc.update("INSERT INTO refund_origin_revocations(grant_id,operation_id) VALUES(?,?) ON CONFLICT DO NOTHING",id,p.id());}
    private void summarize(UUID orderId){var o=db.order(orderId,true);var totals=db.totals(o);if(totals.confirmed()>o.amount())throw new PaymentGatewayException("REFUND_TOTAL_INVALID",false);boolean full=totals.confirmed()>=o.amount();
        // A contradictory later status keeps the confirmed amount and existing blocks, without reapplying access.
        if(full){var confirmed=db.jdbc.query("SELECT * FROM refund_operations WHERE order_id=? AND state='SUCCEEDED' ORDER BY confirmed_at DESC,id LIMIT 1",db::operation,orderId);if(!confirmed.isEmpty())for(var line:db.lines(o))block(o,confirmed.getFirst(),line.orderResourceId());
            // A complete refund identifies the affected origins, but gives no per-resource price split.
            for(var external:db.jdbc.query("SELECT * FROM refund_operations WHERE order_id=? AND state='SUCCEEDED' AND access_state='NEEDS_REVIEW'",db::operation,orderId)){db.jdbc.update("UPDATE refund_operations SET access_state='APPLIED',updated_at=greatest(updated_at,created_at,clock_timestamp()),revision=revision+1 WHERE id=?",external.id());db.audit(null,orderId,external.request(),external.id(),"FULL_REFUND_ACCESS","APPLIED","Full cumulative refund; no monetary allocation inferred");}}
        boolean review=totals.confirmed()+totals.reserved()>o.amount()||Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM refund_operations WHERE order_id=? AND(state='NEEDS_REVIEW' OR(state='SUCCEEDED' AND access_state='NEEDS_REVIEW'))) OR EXISTS(SELECT 1 FROM orders o WHERE o.id=? AND o.payment_refunded AND NOT EXISTS(SELECT 1 FROM refund_operations p WHERE p.order_id=o.id))",Boolean.class,orderId,orderId));
        if(!review&&o.full())full=true;Long old=db.jdbc.queryForObject("SELECT refund_confirmed_minor FROM orders WHERE id=?",Long.class,orderId);if(o.reconciled()==null||old==null||old!=totals.confirmed()||review!=o.review()||full!=o.full())db.jdbc.update("UPDATE orders SET refund_confirmed_minor=?,refund_review_required=?,refund_full=refund_full OR ?,payment_refunded=payment_refunded OR ?,refund_reconciled_at=clock_timestamp(),revision=revision+1 WHERE id=?",totals.confirmed(),review,full,totals.confirmed()>0,orderId);
        if(!review&&!full&&"PAID".equals(o.payment())&&!"READY".equals(o.fulfillment())){db.jdbc.update("UPDATE orders SET fulfillment_status='PENDING',revision=revision+1 WHERE id=?",orderId);db.jdbc.update("UPDATE payment_reconciliation_jobs SET state='PENDING',next_attempt_at=clock_timestamp(),processed_at=NULL,lease_id=NULL,lease_until=NULL,last_error_code=NULL,updated_at=greatest(updated_at,created_at,clock_timestamp()) WHERE order_id=? AND state<>'PROCESSING'",orderId);}
    }
    private Request lockRequest(UUID actor,UUID context,UUID id,String permission){auth.mutation(actor,context,permission);var r=db.request(id,false);db.lockOwner(r.owner());db.order(r.order(),true);r=db.request(id,true);auth.mutation(actor,context,permission);return r;}
    private Operation lockOperation(UUID actor,UUID context,UUID id,String permission){auth.mutation(actor,context,permission);var p=db.operation(id,false);db.lockOwner(p.owner());db.order(p.order(),true);p=db.operation(id,true);auth.mutation(actor,context,permission);return p;}
    private Order ownedOrder(UUID actor,UUID id,boolean admin){var o=db.order(id,false);if(!admin&&!actor.equals(o.owner()))throw error(ApiError.RESOURCE_NOT_FOUND);return o;}
    private static List<RefundAllocation> validateAllocations(List<RefundAllocation> values,long amount,List<RefundLine> lines,boolean full){if(values==null||values.isEmpty()||values.size()>20)throw error(ApiError.INVALID_REFUND_ALLOCATION);Set<UUID> seen=new HashSet<>();long sum=0;for(var a:values){if(a==null||a.orderResourceId()==null||!seen.add(a.orderResourceId())||a.amountMinor()<0||a.amountMinor()>99_999_999||a.accessAction()==null||!Set.of("KEEP","REVOKE").contains(a.accessAction())||lines.stream().noneMatch(l->l.orderResourceId().equals(a.orderResourceId()))||!full&&a.amountMinor()==0&&"REVOKE".equals(a.accessAction()))throw error(ApiError.INVALID_REFUND_ALLOCATION);sum+=a.amountMinor();}if(sum!=amount||full&&(seen.size()!=lines.size()||values.stream().anyMatch(a->!"REVOKE".equals(a.accessAction()))))throw error(ApiError.INVALID_REFUND_ALLOCATION);return values.stream().sorted(Comparator.comparing(a->a.orderResourceId().toString())).toList();}
    public static String requestTag(RefundRequestView value){return EntityTags.forRevision("refund-request",value.id(),value.revision());}
    private static String requestTag(Request value){return EntityTags.forRevision("refund-request",value.id(),value.revision());}
    public static String operationTag(RefundOperationView value){return "\"refund-operation-"+value.id()+"-r"+value.revision()+"-n"+value.notificationStatus()+"-a"+(value.canExecute()?1:0)+(value.canCancel()?1:0)+(value.canReconcile()?1:0)+(value.canDecideAccess()?1:0)+"\"";}
    static String safeCode(String code){return code!=null&&code.matches("[A-Z][A-Z0-9_]{0,63}")?code:"REFUND_RECONCILIATION_UNAVAILABLE";}
    private static UUID uuidUnchecked(java.sql.ResultSet r,String name){try{return uuid(r,name);}catch(java.sql.SQLException unavailable){throw new IllegalStateException("Refund projection unavailable");}}
    private static final Set<String> STATES=Set.of("PREPARED","CALLING","UNKNOWN","PENDING","REQUIRES_ACTION","SUCCEEDED","FAILED","CANCELED","NEEDS_REVIEW");
    private static final Set<String> PROVIDER_STATES=Set.of("pending","requires_action","succeeded","failed","canceled");
    private record Execution(RefundParameters parameters,String providerKey,UUID lease){@Override public String toString(){return "RefundExecution[redacted]";}}
}
